import json
p = r"C:\code\GBA-Rom-Translator\_session_dcbe.jsonl"
rows=[json.loads(l) for l in open(p,encoding='utf-8') if l.strip()]
def text_of(o):
    if isinstance(o,str): return o
    if isinstance(o,list):
        parts=[]
        for b in o:
            if isinstance(b,dict):
                if b.get('type')=='text': parts.append(b.get('text',''))
                elif b.get('type')=='tool-call': parts.append('[tool-call %s]'%b.get('toolName'))
                else: parts.append('['+str(b.get('type'))+']')
            else: parts.append(str(b))
        return '\n'.join(parts)
    return json.dumps(o,ensure_ascii=False)
for i,r in enumerate(rows):
    t=r.get('type')
    if t in ('user/message','session/title','compaction/summary'):
        print('---',i,t)
        print(text_of(r.get('content') or r.get('text') or r.get('summary') or r)[:1500])
