{"command":"@'
import json, io
p = r"C:\code\GBA-Rom-Translator\_session_dcbe.jsonl"
rows=[json.loads(l) for l in open(p,encoding='utf-8') if l.strip()]
out=io.open(r"C:\code\GBA-Rom-Translator\_session_full.md","w",encoding="utf-8")
def txt(blocks):
    parts=[]
    for b in blocks or []:
        if isinstance(b,dict):
            t=b.get('type')
            if t=='text': parts.append(b.get('text',''))
            elif t=='reasoning': parts.append('[REASONING] '+b.get('text','')[:400])
            elif t=='tool-call': parts.append('[TOOL %s] %s'%(b.get('name'), b.get('arguments','')[:400]))
        else: parts.append(str(b))
    return '\n'.join(parts)
for i,r in enumerate(rows):
    t=r.get('type'); d=r.get('data') or {}
    if t=='user/message':
        c=txt(d.get('content'))
        if c.strip().startswith('<system-reminder'): continue
        if c.strip().startswith('Time sampled'): continue
        out.write('\n\n==== [%d] USER ====\n%s\n'%(i,c))
    elif t=='assistant/message':
        m=d.get('message') or {}
        out.write('\n\n---- [%d] ASSISTANT ----\n%s\n'%(i,txt(m.get('content'))))
    elif t=='tool/result':
        c=txt(d.get('content') if isinstance(d.get('content'),list) else [{'type':'text','text':str(d.get('content'))[:600]}])
        out.write('\n-- [%d] RESULT --\n%s\n'%(i,c[:600]))
    elif t=='compaction/summary':
        out.write('\n\n##### [%d] SUMMARY #####\n%s\n'%(i,txt(d.get('summary'))))
out.close()
print('ok')
