import os
from PIL import Image
RUN = r"work/POKEMON_RUBY_AXVJ00/bot/battle_result/20261117T162903_769216"
def blackratio(p):
    im = Image.open(p).convert('RGB'); w,h = im.size; px = im.load()
    black=0; total=0
    for y in range(112,160,2):
        for x in range(0,w,3):
            r,g,b = px[x,y]; total+=1
            if r<8 and g<8 and b<8: black+=1
    return black/total
diff=[]
for n in list(range(1,20))+list(range(40,60))+list(range(75,90)):
    po = os.path.join(RUN,"origin","%03d.png"%n); pt = os.path.join(RUN,"translated","%03d.png"%n)
    if not (os.path.exists(po) and os.path.exists(pt)): continue
    ro, rt = blackratio(po), blackratio(pt)
    if abs(ro-rt) > 0.2:
        diff.append((n, round(ro,3), round(rt,3)))
print("frames where origin vs translated black-ratio differs >0.2:")
for d in diff: print("  ", d)
if not diff: print("   none - both sides identical")
'@ | Set-Content -Encoding UTF8 work\_tear2.py; C:\Python314\python.exe work\_tear2.py","description":"Compare black ratio origin vs translated"}

