{"file_path":"C:\code\GBA-Rom-Translator\configs\POKEMON_RUBY_AXVJ00\hook\src\text\PrintNextChar_hook.c","new_string":"/* 本窗实际可用的段数。
 *
 * 位置公式一个窗要 8 段 × 62 tile = 496；TB 高到 0x212 以上时
 * `TB + 2 + 8*62 > 0x400`，而 GBA tilemap 表项只有 10 bit（< 0x400），
 * 后面的 band 一律越界被静默丢弃。
 *
 * 2026-11-17 硬件实证（bug B2「招式表第二行整行空白」）：
 *   TB=0x320 band4 col2 → 0x41A；TB=0x330 band4 col10 → 0x42A，
 *   全部 > 0x400。招式窗 0x320/0x330（第二行）因此整行空白。
 *   VRAM 对照：origin 帧 080 的 0x300..0x33F 全非零，translated 全 0 字节。
 *
 * 修法：段数按本窗**真实剩余空间**收紧（nseg = ⌊(0x400-TB-2)/62⌋），
 * 再取 band % nseg。这是收紧段数，不是把段打包更多列 ——
 * 只要某窗口真正用到的行数 ≤ nseg，就不会发生行别名。
 * TB ≤ 0x212 时 nseg 恒为 8 ⇒ 背包/对话/图鉴/主菜单逐字节不变。 */
static unsigned grid_band_count(unsigned tb)
{
    unsigned avail;
    unsigned n;

    if ((unsigned)tb + 2u + GRID_SEG_COUNT * GRID_SEG_TILES
        <= GRID_TILE_BITS)
        return GRID_SEG_COUNT;          /* 8 段放得下：维持现状 */
    avail = GRID_TILE_BITS - (unsigned)tb - 2u;
    n = avail / GRID_SEG_TILES;
    return (n < 1u) ? 1u : n;
}

/* row&7 段号。对话底框 L2（y≈17 → band0）与存档信息框地名（y=1 → band0）
 * 撞本征。底框 band0 改映 **band5**（信息框行 y=1/3/5/7/9 → band0..4）。
 *
 * ★ 禁止再映 band6：图鉴说明 Menu_PrintText(..., left=2, top=13)
 *   L1 y=13→band6，L3 y=17→band0；若映到 6 则 L3 踩 L1 → 屏上
 *   「慰人心。」盖住「据说,充足…」（GLOBAL_12PX_MISSING_GLYPHS.md）。
 *
 * ★ 仅左缘（CURSOR_X < 20）：开始菜单「退出」y=16 若也映会踩「保存」。
 *   对话左缘≈4；图鉴说明 left=2；开始菜单 x≈23；YesNo 左≈20。
 *
 * ★★ 禁止把 8 段硬折叠互压来迁就高 TB 窗（`band %= nseg` 且 nseg 由
 *   窗容量算但不管用了几行）：2026-11-16 实测行别名 → row 与 row+nseg
 *   共用同一 62-tile 段、两行文本互相覆盖，战斗结果场景 18 帧底部
 *   48 行纯黑带 + UI 整块上移（对照：不折叠 0 帧撕裂）。
 *   现在的写法只在「本窗物理上放不下 8 段」时收紧段数（见
 *   grid_band_count），且招式窗那种「每窗只打一行」的场景不会被别名。 */
static unsigned grid_band(TextPrinter *win)
{
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);
    unsigned nseg = grid_band_count((unsigned)win_u16(win, WIN_TILE_BASE));

    if (band == 0u && grid_cursor_ty(win) >= 14u
        && win_u8(win, WIN_CURSOR_X) < 20u)
        return 5u % nseg;
    return band % nseg;
}

static uint16_t grid_tile(TextPrinter *win, unsigned col)
{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    return (uint16_t)((unsigned)tb + 2u
            + grid_band(win) * GRID_SEG_TILES
            + 2u * col);
}","old_string":"/* row&7 段号。对话底框 L2（y≈17 → band0）与存档信息框地名（y=1 → band0）
 * 撞本征。底框 band0 改映 **band5**（信息框行 y=1/3/5/7/9 → band0..4）。
 *
 * ★ 禁止再映 band6：图鉴说明 Menu_PrintText(..., left=2, top=13)
 *   L1 y=13→band6，L3 y=17→band0；若映到 6 则 L3 踩 L1 → 屏上
 *   「慰人心。」盖住「据说,充足…」（GLOBAL_12PX_MISSING_GLYPHS.md）。
 *
 * ★ 仅左缘（CURSOR_X < 20）：开始菜单「退出」y=16 若也映会踩「保存」。
 *   对话左缘≈4；图鉴说明 left=2；开始菜单 x≈23；YesNo 左≈20。
 *
 * ★★ 绝对禁止把 band 折叠（band %= nseg）来迁就高 TB 窗的容量
 *   （2026-11-16 18:2x 实测反例，已废弃）：折叠会让 row 与 row+nseg
 *   共用同一 62-tile 段 —— TB=0x300 时 row0 与 row4、row1 与 row5 …
 *   两行文本互相覆盖；战斗结果场景直接恶化为 18 帧底部 48 行纯黑带
 *   + UI 整块上移（对照实验：不折叠 0 帧撕裂 / 折叠 18 帧撕裂）。
 *   band 必须保持 8 段独立；越界由 grid_emit 的 arena 上界保护丢弃。 */
static unsigned grid_band(TextPrinter *win)
{
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);

    if (band == 0u && grid_cursor_ty(win) >= 14u
        && win_u8(win, WIN_CURSOR_X) < 20u)
        return 5u;
    return band;
}

static uint16_t grid_tile(TextPrinter *win, unsigned col)
{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    unsigned hi = grid_arena_hi((unsigned)tb);
    unsigned cx = win_u8(win, WIN_CURSOR_X);
    unsigned natural;

    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    natural = (unsigned)tb + 2u
            + grid_band(win) * GRID_SEG_TILES
            + 2u * col;
    if (natural + 2u <= hi)
        return (uint16_t)natural;

    /* 位置公式天然越界（高 TB 战斗窗 band4+，2026-11-17 B2 硬件实证）：
     * 改走 origin 的**线性槽**语义。pret/pokeruby src/text.c：
     *   PrintGlyph_TextMode0 → GetCursorTileNum(win,x,y)
     *     = tileDataStartOffset + tileDataOffset (+ 行偏移)
     *   AddToCursorX：每跨越 8px 列边界 tileDataOffset += 2。
     * 即原版 tile = TB + 2*（本窗内已消费列数），与屏幕行号（band）无关。
     *
