import os
from PIL import Image
# 检查背包 run 是否整行丢字（干净基线 438dd590 采集）
RUN = r"work/POKEMON_RUBY_AXVJ00/bot/bag_blank_rows/20261117T170213_388647"
def rowink(p,y0,y1,x0=24,x1=112):
    im=Image.open(p).convert('RGB'); px=im.load(); n=0
    for y in range(y0,y1):
        for x in range(x0,x1):
            r,g,b=px[x,y]
            if r<160 and g<160 and b<160: n+=1
    return n
rows=[(32,46),(48,62),(64,78),(80,94),(96,110),(112,126),(128,142),(144,158)]
worst=[]
