import os
from PIL import Image
# 新 ROM 5d88eb72 的背包/菜单也扫一遍整行空白，确认兜底没引入新空白
RUNS = {
 'menu(new)': r"work/POKEMON_RUBY_AXVJ00/bot/battle_menu_audit/20261117T172016_965306",
 'result(new)': r"work/POKEMON_RUBY_AXVJ00/bot/battle_result/20261117T172016_975857",
}
for name, RUN in RUNS.items():
    bad=[]
    cnt=0
    for n in range(1,1000):
        po=os.path.join(RUN,"origin","%03d.png"%n); pt=os.path.join(RUN,"translated","%03d.png"%n)
        if not (os.path.exists(po) and os.path.exists(pt)): continue
        cnt+=1
        a=Image.open(po).convert('L'); b=Image.open(pt).convert('L')
        pa=a.load(); pb=b.load()
        # 每 8 行一条带，比较墨量
        for band in range(20):
            y0=band*8
            ia=ib=0
            for y in range(y0,min(y0+8,160)):
                for x in range(0,240,2):
                    if pa[x,y]<140: ia+=1
                    if pb[x,y]<140: ib+=1
            if ia>25 and ib<ia*0.3: bad.append((n,band,ia,ib))
    print(name, "pairs=",cnt, "blank-bands:", len(bad), bad[:10])
