{"command":"cd C:\code\GBA-Rom-Translator; @'
import os
from PIL import Image
# 更严格判据：同一帧里 origin 该带是"文字墨迹"（不是 UI 图形/背景），translated 却空
# 且要求 origin/translated 整体画面相似度足够高（同一游戏阶段），否则跳过
def bands(p):
    im=Image.open(p).convert('L'); px=im.load()
    out=[]
    for b in range(20):
        y0=b*8; n=0
        for y in range(y0,min(y0+8,160)):
            for x in range(0,240):
                if px[x,y]<140: n+=1
        out.append(n)
    return out
def sim(pa,pb):
    a=Image.open(pa).convert('L'); b=Image.open(pb).convert('L')
    la,lb=a.load(),b.load(); same=0; tot=0
    for y in range(0,160,2):
        for x in range(0,240,2):
            tot+=1
            if abs(la[x,y]-lb[x,y])<40: same+=1
    return same/tot
for name, RUN in (('menu', r"work/POKEMON_RUBY_AXVJ00/bot/battle_menu_audit/20261117T172016_965306"),
                  ('result', r"work/POKEMON_RUBY_AXVJ00/bot/battle_result/20261117T172016_975857")):
    bad=[]
    for n in range(1,1000):
        po=os.path.join(RUN,"origin","%03d.png"%n); pt=os.path.join(RUN,"translated","%03d.png"%n)
        if not (os.path.exists(po) and os.path.exists(pt)): continue
        s=sim(po,pt)
        if s<0.85: continue      # 不是同一游戏阶段，跳过
        ba,bt=bands(po),bands(pt)
        for i,(a,b) in enumerate(zip(ba,bt)):
            if a>40 and b<6: bad.append((n,i,round(s,2),a,b))
    print(name, "same-stage blank bands:", len(bad), bad[:12])
'@ | Set-Content -Encoding UTF8 work\_bands2.py; C:\Python314\python.exe work\_bands2.py","description":"Strict same-stage blank band detection"}

