def sim(pa,pb):
    a=Image.open(pa).convert('L'); b=Image.open(pb).convert('L')
    la,lb=a.load(),b.load(); same=0; tot=0
    for y in range(0,160,2):
        for x in range(0,240,2):
            tot+=1
