{"file_path":"C:\code\GBA-Rom-Translator\configs\POKEMON_RUBY_AXVJ00\hook\src\text\PrintNextChar_hook.c","new_string":"/* 12px 相位：从串首（或最近换行 / 清窗口）到 index 累计像素，取低 3 位。
 * 零 EWRAM 状态 —— 原版 tm0 用 TILE_OFFSET 累加器，这里连累加器都不要。
 * FC 参数必须按类型跳过，否则颜色/字体号字节会被误当成 PCS 或 F7 前缀。 */
static unsigned fc_arg_count(uint8_t type)
{
    switch (type) {
    case FC_FG:
    case FC_BG:
    case FC_SHADOW:
    case FC_PALETTE:
    case FC_FONT:
    case FC_PAUSE:
    case FC_SHIFT_TILE_X:
    case FC_SHIFT_TILE_Y:","old_string":"/* 位置公式越界（tile 号 ≥ 0x400，tilemap 表项只有 10 bit）时的兜底落点。
 *
 * 为什么需要它（2026-11-17 硬件实证，bug B2）：
 *   招式表第二行用的战斗窗 TB=0x320/0x330，band=4 时
 *   `TB + 2 + band*62 + 2*col` = 0x41A/0x42A > 0x400 ⇒ grid_emit 静默丢弃
 *   ⇒ 屏上「二连踢/火焰踢」整行空白。
 *   VRAM 对照：origin 帧 080 的 tile 0x300..0x33F 全非零，translated 全 0。
 *
 * 为什么不能用 band 折叠 / 线性槽（都已实测证伪，见 grid_band 注释）：
 *   那两种做法改的是**所有格子的落点**，同窗不同行会别名到同一段 tile，
 *   两行文本互相覆盖 → 战斗结算场景 10–23 帧底部纯黑带。
 *
 * 本函数只处理「本来就会被丢弃、屏幕上什么都没有」的格子，
 * 按 origin 的线性槽语义（pret/pokeruby src/text.c：
 *   GetCursorTileNum = tileDataStartOffset + tileDataOffset，
 *   AddToCursorX 每跨 8px 列 +2）在**本窗 arena 内**挑一对没被引用的 tile：
 *   判据与 tile 冲突规避同源 —— 本窗 tilemap 未引用 + VRAM 该对为空。
 * 因此它严格是「从无到有」，不可能覆盖别的格子已经画好的内容。
 *
 * 返回 0xFFFF 表示本窗确实没有空位（调用方保持旧行为：丢弃）。 */
static uint16_t grid_tile_overflow(TextPrinter *win, unsigned col,
                                   unsigned ncols)
{
    uint32_t used[GRID_TILE_BITS / 32u];
    uint32_t base = grid_tile_base(win);
    const uint8_t *tpl = win_template(win);
    const uint16_t *map = 0;
    unsigned tb = (unsigned)win_u16(win, WIN_TILE_BASE);
    unsigned hi = grid_arena_hi(tb);
    unsigned ty = grid_cursor_ty(win);
    unsigned n, need = 2u * ncols;

    if (!base || !tpl)
        return 0xFFFFu;
    map = (const uint16_t *)(const void *)(uintptr_t)win_u32(tpl, TPL_TILEMAP);

    /* 先复用本格已有的表项：重印同一格时不搬家，避免逐帧换 tile 抖动。 */
    if (map && col < GRID_TILEMAP_W && ty < GRID_TILEMAP_W) {
        unsigned v = grid_tilemap_entry(map, col, ty);
        if (v >= tb + 2u && v + need <= hi)
            return (uint16_t)v;
    }

    /* used 位图：本窗 tilemap 已引用的 tile（排除本格自身）。
     * 传 0xFFFF 当 t0 只是为了让 grid_tile_taken 把位图填好。 */
    (void)grid_tile_taken(win, col, (uint16_t)0xFFFFu, used);

    for (n = tb + 2u; n + need <= hi; n += 2u) {
        unsigned k;
        int ok = 1;
        for (k = 0u; k < need; k += 2u) {
            unsigned t = n + k;
            if (used[t >> 5] & (1u << (t & 31u))) { ok = 0; break; }
            if (!grid_tile_vram_blank(base, t)) { ok = 0; break; }
        }
        if (ok)
            return (uint16_t)n;
    }
    return 0xFFFFu;
}

