{"command":"cd C:\code\GBA-Rom-Translator; @'
import os, struct
R=r"work/POKEMON_RUBY_AXVJ00/bot/battle_menu_audit/20261118T113750_644748"
# 战斗窗 tilemap @ 0x0600C000 (模板 +0x10 = 0x0600c000)
# 检查 0x1F0..0x400 这些 tile 是否被任何 tilemap 引用
for side in ("origin","translated"):
    v=open(os.path.join(R,side,"044.vram.bin"),'rb').read()
    print(f"=== {side} 044.vram")
    for tmbox in (0x0600C000, 0x06000000):
        base=tmbox-0x06000000
        if base+0x800 > len(v): continue
        used=set()
        for i in range(0, 32*32):
            e=struct.unpack_from('<H',v,base+i*2)[0]
            t=e&0x3FF
            if t: used.add(t)
        hi=[t for t in used if 0x1F0 <= t < 0x400]
        print(f"  tilemap {tmbox:#010x}: 引用 {len(used)} 个 tile, 其中 0x1F0..0x3FF 有 {len(hi)} 个")
        if hi: print(f"    {sorted(hi)[:20]}")
'@ | Set-Content -Encoding UTF8 work\_tilemap.py; $env:PYTHONIOENCODING='utf-8'; C:\Python314\python.exe work\_tilemap.py","description":"Check tile usage above 0x1F0"}

