{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    return (uint16_t)((unsigned)tb + 2u
            + (grid_row(win) & (GRID_SEG_COUNT - 1u)) * GRID_SEG_TILES
            + 2u * col);
}","old_string":"static uint16_t grid_tile(TextPrinter *win, unsigned col)
{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);
    unsigned t;
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    t = (unsigned)tb + 2u + band * GRID_SEG_TILES + 2u * col;

    /* ★ 高 TB 窗压缩段宽（2026-11-18 实测定案，修战斗对话框整框空白）
     *
     * 网格公式按「一行 31 列 × 8 段」切 tile（每段 62 tile），前提是窗口
     * TB 小、能放下完整 8 段。战斗对话框窗（tpl=0x081BB3F4）实测：
     *   TB=0x1B8、cursor_ty=35 ⇒ row=17、band=1
     *   标准网格落点 = 0x1B8+2+62 = **0x1F8 > 0x1F0**
     * col=0 就越界 → grid_emit 的保护分支每个字都 return → 整框空白
     * （对话/主菜单四项/招式表/PP 全不显示，只剩空框 + ▼/▶）。
     *
     * 该窗实际可用空间：[TB+2, GRID_TILE_LIMIT) = [0x1BA, 0x1F0) = 54 tile。
     * 放不下 1 个标准段（62），但可以放 **2 个压缩段**（各 27 tile = 13 列）。
     * 战斗对话框/菜单最多 2 行文本，13 列 × 2 行足够。
     *
     * 判据（三条同时成立才启用，避免误伤其它窗口）：
     *   1) TB < GRID_TILE_LIMIT —— TB=0x400/0x300 的战斗菜单窗本来就在
     *      0x1F0 之外且工作正常，不受这条保护线约束，不能碰；
     *   2) 标准网格越界（t+2 > LIMIT）—— 正常窗口不走这里；
     *   3) band != 0 —— band0 本身没偏移。
     * 压缩段宽 = (LIMIT - TB - 2) / 2，向下取偶数，保证 2 行都放得下。 */
    if ((unsigned)tb < GRID_TILE_LIMIT
        && band != 0u
        && t + 2u > GRID_TILE_LIMIT) {
        unsigned avail = (unsigned)GRID_TILE_LIMIT - (unsigned)tb - 2u;
        unsigned seg = (avail / 2u) & ~1u;      /* 每段 tile 数（偶数） */

        if (seg >= 4u) {
            unsigned ct = (unsigned)tb + 2u + (band & 1u) * seg + 2u * col;

            if (ct + 2u <= GRID_TILE_LIMIT)
                return (uint16_t)ct;
        }
        /* 压缩段也放不下：退到本窗最低段，至少让字出来 */
        {
            unsigned lin = (unsigned)tb + 2u + 2u * col;

            if (lin + 2u <= GRID_TILE_LIMIT)
                return (uint16_t)lin;
        }
    }
    return (uint16_t)t;
}"}

