/* 字库：0x09000000 起 7168 槽 × 128B，顺序 TL(0) BL(32) TR(64) BR(96)，","old_string":"#define GRID_TILE_LIMIT     0x1F0u                  /* 每窗 arena 容量（相对 TB） */

/* 本窗 arena 的**相对**上界 = TB + 0x1F0，并夹到 10 bit tile 号上限。
 *
 * ★ 为什么必须用相对上界（2026-11-15 首次证实，2026-11-18 复证）：
 *   GRID_TILE_LIMIT 描述的是「一个窗口从 TB 起能占多少 tile」，不是
 *   屏幕上的绝对位置。早期代码拿它当**绝对**上限（`t0 > 0x1F0`），
 *   只对 TB≈0/1 的对话窗成立；战斗窗 TB 高达 0x1B8~0x2C0，
 *   任意列都判超限 → **整窗静默不画**（遇敌台词/主菜单/招式表/PP 全空，
 *   只剩空框 + ▼/▶）。详见 docs/research/BATTLE_EMPTY_TEXT.md。
 *
 * 上界取 min(tb + 0x1F0, 0x400)：tilemap 表项只有 10 bit 存 tile 号，
 * 超过 0x3FF 会被硬件截断写到无关位置（背景色错/字串位）。
 * TB=0x1B8 时上界 = 0x3A8；TB=0x2C0 时上界 = 0x400（夹到 0x400）。 */
static inline unsigned grid_arena_hi(unsigned tb)
{
    unsigned hi = tb + GRID_TILE_LIMIT;

    return hi > GRID_TILE_BITS ? GRID_TILE_BITS : hi;
}

