{"command":"cd C:\code\GBA-Rom-Translator; @'
import os, struct
R=r"work\POKEMON_RUBY_AXVJ00\bot\battle_menu_audit\20261118T153231_447709"
v=open(os.path.join(R,"origin","044.vram.bin"),'rb').read()
# 找哪个 tilemap 槽引用了 0x1B8
for base in range(0,0x10000,0x800):
    if base+0x800>len(v): break
    used=set()
    for i in range(1024):
        t=struct.unpack_from('<H',v,base+i*2)[0]&0x3FF
        if t: used.add(t)
    if 0x1B8 in used:
        # 找它出现的位置
        pos=[]
        for y in range(32):
            for x in range(32):
                t=struct.unpack_from('<H',v,base+(y*32+x)*2)[0]&0x3FF
