{"content":"/**
 * evidence-gate — 阻止「没抓数据就改代码」。
 *
 * 背景（2026-11-18 用户诊断）：本代理在 GBA-Rom-Translator 上反复
 * 「猜假设 → 改代码 → 跑 bot → 看图 → 猜错」，从不使用仓库里现成的
 * GDB 探针 / VRAM dump / 反汇编通道。AGENTS.md 的规则约束不了它，
 * 因此把约束下沉到工具层：改受保护源码前，必须已有本轮证据。
 *
 * 机制：
 *   - 监听 `tools/pre-execute`（waterfall，可 deny）
 *   - 命中 edit / write / apply_patch 且目标在受保护前缀内
 *   - 读 <workspace>/work/.evidence_log.jsonl
 *   - 三类证据（static / gdb / bot）必须齐全，且每条时间戳都晚于
 *     受保护源码的最新 mtime（防止拿旧证据给新改动背书）
 *   - 不满足则 deny，reason 里写清缺什么、怎么补
 *
 * 证据写入由 scripts/evidence_gate.py --record 完成。
 */

const fs = require('node:fs')
const path = require('node:path')

const DEFAULTS = {
  workspace: '',
  guardedTools: ['edit', 'write', 'apply_patch'],
  protectedPrefixes: [],
  requiredKinds: ['static', 'gdb', 'bot'],
}

const KIND_LABEL = {
  static: '静态反汇编（objdump / ROM 字节 / tilemap 读回）',
  gdb: 'GDB 运行时探针（bot/run.py --gdb <probe>）',
  bot: 'bot 场景采集（bot/run.py <scene> + 帧比对）',
}

const KIND_HOWTO = {
  static: 'python scripts\\evidence_gate.py --record static --detail "objdump <addr>"',
  gdb: 'python scripts\\evidence_gate.py --record gdb --detail "bot --gdb InitTextPrinter"',
  bot: 'python scripts\\evidence_gate.py --record bot --detail "<scene> N pairs"',
}

function logFile(workspace) {
  return path.join(workspace, 'work', '.evidence_log.jsonl')
}

/** 受保护源码的最新 mtime；无文件返回 0。 */
function protectedMtime(workspace, prefixes) {
  let newest = 0
  const exts = new Set(['.c', '.h', '.s', '.asm', '.py'])
  const walk = (dir) => {
    let ents
    try {
      ents = fs.readdirSync(dir, { withFileTypes: true })
    } catch {
      return
    }
    for (const e of ents) {
      const p = path.join(dir, e.name)
      if (e.isDirectory()) {
        walk(p)
      } else if (exts.has(path.extname(e.name))) {
        try {
          const m = fs.statSync(p).mtimeMs / 1000
          if (m > newest) newest = m
        } catch {
          /* ignore */
        }
      }
    }
  }
  for (const pre of prefixes) walk(path.join(workspace, pre))
  return newest
}

/** 读证据日志，返回本轮有效的证据（kind -> record）。 */
function freshEvidence(workspace, requiredKinds) {
  const file = logFile(workspace)
  let raw = ''
  try {
    raw = fs.readFileSync(file, 'utf8')
  } catch {
    return {}
  }
  const recs = []
  for (const line of raw.split('\n')) {
    const t = line.trim()
    if (!t) continue
    try {
      recs.push(JSON.parse(t))
    } catch {
      /* ignore malformed */
    }
  }
  const srcT = protectedMtime(workspace, DEFAULTS.protectedPrefixes)
  const out = {}
  for (const r of recs) {
    if (!r || typeof r.t !== 'number') continue
    if (r.t <= srcT) continue // 早于最近一次源码改动 ⇒ 失效
    if (requiredKinds.includes(r.kind)) out[r.kind] = r
  }
  return out
}

/** 从工具参数里取目标文件路径。 */
function targetPath(args) {
  if (!args || typeof args !== 'object') return ''
  const cand = args.file_path ?? args.path ?? args.filePath ?? args.target
  return typeof cand === 'string' ? cand : ''
}

export const name = 'evidence-gate'

export function apply(ctx, config) {
  const cfg = { ...DEFAULTS, ...(config || {}) }
  const workspace = cfg.workspace || process.cwd()
  const prefixes = cfg.protectedPrefixes.length
    ? cfg.protectedPrefixes
    : DEFAULTS.protectedPrefixes

  const isProtected = (absPath) => {
    const norm = absPath.replace(/\\/g, '/')
    return prefixes.some((pre) => norm.includes(pre.replace(/\\/g, '/')))
  }

  ctx.on('tools/pre-execute', async (execution, next) => {
    const toolName = execution?.name
    if (!cfg.guardedTools.includes(toolName)) return next()

    const tp = targetPath(execution.arguments)
    if (!tp) return next()

    // 相对路径按 workspace 解析
    const abs = path.isAbsolute(tp) ? tp : path.join(workspace, tp)
    if (!isProtected(abs)) return next()

    // 检查本轮证据
    const srcT = protectedMtime(workspace, prefixes)
    const file = logFile(workspace)
    let recs = []
    try {
      recs = fs
        .readFileSync(file, 'utf8')
        .split('\n')
        .map((l) => l.trim())
        .filter(Boolean)
        .map((l) => {
          try {
            return JSON.parse(l)
          } catch {
            return null
          }
        })
        .filter(Boolean)
    } catch {
      recs = []
    }

    const fresh = {}
    for (const r of recs) {
      if (typeof r.t !== 'number') continue
      if (r.t <= srcT) continue
      if (cfg.requiredKinds.includes(r.kind)) fresh[r.kind] = r
    }

    const missing = cfg.requiredKinds.filter((k) => !fresh[k])
    if (missing.length === 0) return next()

    const lines = [
      '编译/改码被拒绝：本轮缺少运行时证据。',
      '',
      '你正在修改受保护的渲染/流水线源码，但还没有用硬数据确认现状。',
      '仓库里已有现成通道（bot/run.py --gdb、VRAM dump、objdump），不要靠猜。',
      '',
      '必须齐全的证据（且都要晚于最近一次源码改动）：',
    ]
    for (const k of cfg.requiredKinds) {
      if (fresh[k]) {
        lines.push(`  ✓ ${KIND_LABEL[k] || k}`)
      } else {
        lines.push(`  ✗ ${KIND_LABEL[k] || k}  —— 缺`)
      }
    }
    lines.push('', '补齐方式：')
    for (const k of missing) lines.push(`  ${KIND_HOWTO[k] || k}`)
    lines.push(
      '',
      '先跑数据，再改代码。这三类证据就是本仓库既定的工作流',
      '（docs/HOOK_DEBUG_WORKFLOW.md：静态分析 → GDB 探针 → bot 验证 → 改码）。'
    )

    return {
      kind: 'deny',
      reason: lines.join('\n'),
    }
  })
}
