{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);
    unsigned t;
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    t = (unsigned)tb + 2u + band * GRID_SEG_TILES + 2u * col;

    /* ★ 高 TB 窗改用原版线性公式（2026-11-18 实测定案，修 BUG-1 战斗框空白）
     *
     * 实测证据链（全部来自 GDB + VRAM，非推测）：
     *
     * 1) GDB `InitTextPrinter` 抓战斗窗真实参数：
     *      对话框  TB=0x0090 curX=2  curTX=0 curY=15 TILE_OFF=4 textMode=0 fn=3
     *      主菜单  TB=0x0190 curX=19 curTX=10 curY=15 TILE_OFF=4
     *      招式表  TB=0x0300/310/320/330 curY=55
     *
     * 2) GDB `UpdateTilemap` 抓原生 ROM 实际写入的 tile 号：
     *      [UTM] win=0x03004170 u=0x0094 l=0x0095 格=(2+16,15+0)->#498
     *      tilemap@0x0600C000 entry@0x0600C3E4 像素落点=0x06001280
     *   ⇒ 原生写入 tile **0x94**，而 0x94 = TB(0x90) + TILE_OFF(4) + 2*curTX(0)
     *   ⇒ 原版公式：`tile = TB + TILE_OFF + 2 * curTX`（线性，与行号无关）
     *
     * 3) 我们的网格公式给 0x90+2+7*62+2*2 = **0x248**，
     *    > GRID_TILE_LIMIT(0x1F0) ⇒ grid_emit 越界保护直接 return，
     *    战斗窗 C 引擎写入次数 = **0**（GDB 统计：58 次全是开始菜单，
     *    战斗窗 29 次全来自原生 ROM）。
     *
     * 4) VRAM 对照：tile 0x94 两侧都有内容，但 0x96..0xA8
     *    origin 32/32 非零 vs translated 0/32 全空 ⇒ 字没画出来。
     *
     * 修复：网格公式越界、而原版线性公式落点合法时，采用原版公式。
     * 只在越界时切换，正常窗口（TB≈0/1）行为完全不变。 */
    if (t + 2u > GRID_TILE_LIMIT) {
        unsigned off = (unsigned)win_u16(win, WIN_TILE_OFFSET);
        unsigned rel = (unsigned)win_u8(win, WIN_CURSOR_TILE_X);
        unsigned lin = (unsigned)tb + off + 2u * rel;

        if (lin >= (unsigned)tb && lin + 2u <= GRID_TILE_BITS)
            return (uint16_t)lin;
    }
    return (uint16_t)t;
}","old_string":"static uint16_t grid_tile(TextPrinter *win, unsigned col)
{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    return (uint16_t)((unsigned)tb + 2u
            + (grid_row(win) & (GRID_SEG_COUNT - 1u)) * GRID_SEG_TILES
            + 2u * col);
}"}

