{"file_path":"C:\code\GBA-Rom-Translator\configs\POKEMON_RUBY_AXVJ00\hook\src\text\PrintNextChar_hook.c","new_string":"/* ★ 高 TB 窗线性分配的 TILE_OFFSET 保护（2026-11-18，方案取自 master 分支）
 *
 * 背景：`textMode==0` 的高 TB 窗（战斗对话框 TB=0x90 / 主菜单 0x190 /
 * 招式表 0x300-0x330）走原版线性分配：
 *     tile_upper = TB + TILE_OFFSET + 0
 *     tile_lower = TB + TILE_OFFSET + 1
 *     每字写完 TILE_OFFSET += 2
 *
 * 但原生代码会在换段时把 TILE_OFFSET 清零。GDB 实测（本仓）：
 *     col=2 OFF=4 -> 0x94  ✓
 *     col=3 OFF=6 -> 0x96  ✓
 *     col=4 OFF=8 -> 0x98  ✓
 *     col=6 OFF=0 -> 0x90  ✗  ← 被清零
 *     col=10 OFF=16 -> 0xA0 ✓
 *     col=17 OFF=1 -> 0x91  ✗  ← 又清零
 * 清零后 tile 回到段首，字全叠在一起（屏上「战肖／背径」而非「战斗／背包」）。
 *
 * master 分支 `text_render.c:497-514` 的解法：
 *     画字前若 `off_now < off_last` 则把 off_now 恢复成 off_last；
 *     画完把 off_last 更新成当前 off。
 * 即「记住上次的 TILE_OFFSET，发现被重置就恢复」。
 * 这里照搬，地址同 master（EWRAM 0x0203FF82，实测不与 DIAG 区冲突）。 */
#define CHS_LAST_OFF_ADDR 0x0203FF82u

static unsigned grid_last_off_get(void)
{
    return (unsigned)*(volatile uint16_t *)(uintptr_t)CHS_LAST_OFF_ADDR;
}

static void grid_last_off_set(unsigned v)
{
    *(volatile uint16_t *)(uintptr_t)CHS_LAST_OFF_ADDR = (uint16_t)v;
}

/* 判断本窗是否走「高 TB 线性分配」。条件与 master `scene_should_use_linear`
 * 一致：textMode==0，且网格公式会越界（本仓网格只对 TB≈0/1 成立）。 */
static int grid_use_linear(TextPrinter *win, unsigned col)
{
    unsigned tb = (unsigned)win_u16(win, WIN_TILE_BASE);
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);
    unsigned t;

    if (win_u8(win, WIN_TEXTMODE) != 0u)
        return 0;
    t = tb + 2u + band * GRID_SEG_TILES + 2u * col;
    return t + 2u > GRID_TILE_LIMIT;
}

static uint16_t grid_tile(TextPrinter *win, unsigned col)
{
    uint16_t tb = win_u16(win, WIN_TILE_BASE);
    unsigned band = grid_row(win) & (GRID_SEG_COUNT - 1u);
    unsigned t;
    /* textMode3：GetBlankTileNum = TB+1。若 arena 从 TB 起算，band0/col0
     * 的 lower 正好是 TB+1 → 写汉字/▶ 时踩碎「空白」模板；开始菜单
     * RedrawMenuCursor 再 Blank 把格指回 TB+1，屏上冒灰影残墨
     *（bot：START 开→关→开→上下，残墨色 (74,74,74)=阴影灰）。 */
    t = (unsigned)tb + 2u + band * GRID_SEG_TILES + 2u * col;

    if (grid_use_linear(win, col)) {
        unsigned off = (unsigned)win_u16(win, WIN_TILE_OFFSET);
        unsigned last = grid_last_off_get();

        /* TILE_OFFSET 被原生代码清零时恢复（master 同款保护） */
        if (last != 0u && off < last) {
            off = last;
            win_set_u16(win, WIN_TILE_OFFSET, (uint16_t)off);
