{"file_path":"C:\code\GBA-Rom-Translator\configs\POKEMON_RUBY_AXVJ00\hook\src\text\PrintNextChar_hook.c","new_string":"/* 本窗当前字的序号 k（从文本流重算）。
 *
 * TEXT_INDEX 是**已消费的字节数**（入口已把当前字推进过），
 * 所以数到 index 就是「已经输出过的字数」，正是原版 TILE_OFFSET 的语义。
 * 实测战斗对话框 index 序列 1,5,6,10,14,18,22,23,27,31,35,39 ——
 * F7 占 4 字节，所以每字 +4（夹着 FC 控制码时 +1）。 */
static unsigned grid_char_index(TextPrinter *win)
{
    const uint8_t *text =
        (const uint8_t *)(uintptr_t)win_u32(win, WIN_TEXT_PTR);
    uint16_t index = win_u16(win, WIN_TEXT_INDEX);

    return grid_char_count(text, index);
}","old_string":"/* 本窗当前字的序号 k（从文本流重算）。 */
static unsigned grid_char_index(TextPrinter *win)
{
    const uint8_t *text =
        (const uint8_t *)(uintptr_t)win_u32(win, WIN_TEXT_PTR);
    uint16_t index = win_u16(win, WIN_TEXT_INDEX);

    /* 入口已把 TEXT_INDEX 推到下一个字节，当前字起点 = index - 字长。
     * 直接数到 index 会把「正在打的这个字」算进去，所以减 1。 */
    if (index == 0u)
        return 0u;
    return grid_char_count(text, (uint16_t)(index - 1u));
}"}

