static unsigned fc_arg_count(uint8_t type)
{
    switch (type) {
    case FC_FG:
    case FC_BG:
    case FC_SHADOW:
    case FC_PALETTE:
    case FC_FONT:
    case FC_PAUSE:
    case FC_SHIFT_TILE_X:
    case FC_SHIFT_TILE_Y:
        return 1u;
    case FC_ALLCOLORS:
        return 3u;
    case FC_PLAYBGM:
    case FC_PLAYSE:
        return 2u;
    default:
        return 0u;   /* FC_ESCAPE 的被转义字节留给下一轮当普通 token 计宽 */
    }
}

