        if (c == 0xFEu || c == 0xFBu) {       /* 换行 / 等待清屏：重新计数 */
            n = 0u;
            ++i;
            continue;
        }
        if (c == 0xFCu) {
            uint8_t type = (i + 1u < index) ? text[i + 1u] : 0u;
            unsigned step = 2u + fc_arg_count(type);

            if (type == FC_CLEARWINDOW)
                n = 0u;
            i = (uint16_t)(i + step);
            continue;
